\title{Ramsey Theory: Exact Values, Erd\H{o}s--Szekeres Bounds,\\ and a Probabilistic Sandwich for the Diagonal}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
We present a unified, fully formalized development of finite two-color Ramsey theory built on a single primitive: the \emph{arrow relation} $\arrows{n}{s}{t}$. Within this framework we establish the three classically known exact small Ramsey numbers $\R(3,3)=6$, $\R(3,4)=9$, and $\R(4,4)=18$; the Erd\H{o}s--Szekeres recursion $\R(s+1,t+1) \le \R(s,t+1)+\R(s+1,t)$ and its closed binomial form $\R(s+1,t+1) \le \binom{s+t}{s}$; the exponential diagonal ceiling $\R(k+1,k+1)\le 4^k$; the Erd\H{o}s probabilistic lower bound, realized as an exact finite union-bound count, giving $\R(k,k) > n$ whenever $2\binom{n}{k} < 2^{\binom{k}{2}}$; and a two-sided \emph{exponential sandwich} $2^{m-1} < \R(2m,2m) \le 4^{2m-1}$ for all $m\ge 4$. The lower-bound constructions are concrete: the pentagon $C_5$ for $\R(3,3)$, a circulant graph on eight vertices for $\R(3,4)$, and the Paley graph on $17$ vertices for $\R(4,4)$. A handshake-parity obstruction is isolated as a reusable lemma underlying the $\R(3,4)$ upper bound. We also record the connection to van der Waerden's theorem on monochromatic arithmetic progressions as the arithmetic shadow of the Hales--Jewett theorem. Every result has been formally verified.
\end{abstract}

\section{Introduction}

Ramsey theory makes precise the slogan that \emph{complete disorder is impossible}: in any sufficiently large structure, any finite coloring must contain a highly ordered monochromatic substructure. The prototypical setting colors the edges of a complete graph with two colors (red/blue) and seeks monochromatic cliques.

Despite the elementary statement, exact Ramsey numbers are notoriously hard. Only finitely many values are known, and the asymptotic growth rate of the diagonal numbers $\R(k,k)$ remains open after eight decades, trapped between $\sqrt 2$ and $4$ as a base of exponential growth. This paper formalizes the foundational layer on one framework: exact small values via explicit constructions, the Erd\H{o}s--Szekeres upper bounds, the probabilistic lower bound as an exact finite count, and the resulting diagonal sandwich.

\subsection{Notation}
A two-coloring of the complete graph on $V$ is encoded by a single graph $G$ on $V$: edges of $G$ are \textbf{red}, edges of the complement $G^{c}$ are \textbf{blue}. A red $s$-clique is an $s$-clique of $G$; a blue $t$-clique is an $s$-clique of $G^c$. We write $K_r$ for a clique on $r$ vertices.

\section{The arrow framework}

\begin{definition}[Arrow relation, \texttt{Arrows}]
For naturals $n,s,t$, we say $\arrows{n}{s}{t}$ if for every vertex type $V$, every coloring $G$ on $V$, and every finite $W \subseteq V$ with $|W|\ge n$, there exists $S\subseteq W$ that is a red $s$-clique or a blue $t$-clique. The Ramsey number is $\R(s,t)=\min\{n : \arrows{n}{s}{t}\}$.
\end{definition}

\begin{lemma}[Vertex monotonicity, \texttt{Arrows.mono}]
If $\arrows{n}{s}{t}$ and $n\le n'$, then $\arrows{n'}{s}{t}$.
\end{lemma}
\begin{proof}
A vertex set of size $\ge n'$ has size $\ge n$.
\end{proof}

\begin{lemma}[Color symmetry, \texttt{arrows\_symm}, \texttt{arrows\_iff\_symm}]
$\arrows{n}{s}{t}$ iff $\arrows{n}{t}{s}$; hence $\R(s,t)=\R(t,s)$.
\end{lemma}
\begin{proof}[Proof sketch]
Apply the hypothesis to $G^c$; since $(G^c)^c=G$, the two clique types swap.
\end{proof}

\section{The Erd\H{o}s--Szekeres recursion and the binomial bound}

\begin{theorem}[Inductive step, \texttt{arrows\_step}]
If $\arrows{m}{s}{t+1}$ and $\arrows{n}{s+1}{t}$ with $m,n>0$, then $\arrows{m+n}{s+1}{t+1}$.
\end{theorem}
\begin{proof}[Proof sketch]
Let $|W|\ge m+n$ and fix $v\in W$. Partition $W\setminus\{v\}$ into the red- and blue-neighborhoods $R_v, B_v$ of $v$. Since $|R_v|+|B_v|\ge m+n-1$, one of them is large enough to apply a recursive call; a same-color clique found there extends through $v$ by one vertex, otherwise the opposite-color clique is already large enough.
\end{proof}

\begin{theorem}[Binomial bound, \texttt{arrows\_recursion}, \texttt{arrows\_binomial\_bound}]
For all $s,t$, $\arrows{\binom{s+t}{s}}{s+1}{t+1}$, i.e.\ $\R(s+1,t+1)\le \binom{s+t}{s}$.
\end{theorem}
\begin{proof}[Proof sketch]
Double induction on $s,t$ with base cases $\arrows{1}{1}{b}$ and $\arrows{1}{a}{1}$, combining \texttt{arrows\_step} with Pascal's rule $\binom{s+t}{s}=\binom{s-1+t}{s-1}+\binom{s+t-1}{s}$.
\end{proof}

\section{Exact small values}

\begin{theorem}[$\R(3,3)=6$, \texttt{ramsey\_three\_three}]
$\arrows{6}{3}{3}$ and $\neg\,\arrows{5}{3}{3}$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper: the instance $s=t=2$ gives $\binom{4}{2}=6\to(3,3)$. Lower: the pentagon $C_5$ on $\mathbb{Z}/5$ has triangle-free red edges, and its complement is again a $5$-cycle, hence triangle-free; so $5\not\to(3,3)$.
\end{proof}

\begin{theorem}[$\R(3,4)=9$, \texttt{ramsey\_three\_four}]
$\arrows{9}{3}{4}$ and $\neg\,\arrows{8}{3}{4}$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper: a clique-free coloring of $9$ vertices forces every vertex to have red-degree exactly $3$ (odd), contradicting the parity obstruction below. Lower: the circulant on $\mathbb{Z}/8$ with $a\sim b$ iff $a-b\in\{1,4\}$ has no red triangle and no blue $K_4$.
\end{proof}

\begin{lemma}[Parity obstruction, \texttt{red\_degree\_parity\_obstruction}]
For any coloring $G$ and finite $W$ with $|W|$ odd, not every $v\in W$ can have odd red-degree inside $W$.
\end{lemma}
\begin{proof}
$\sum_{v\in W}\deg^{\mathrm{red}}_W(v)$ counts each red edge twice, hence is even (\texttt{red\_nbrs\_sum\_even}); but a sum of an odd number of odd terms is odd.
\end{proof}

\begin{theorem}[$\R(4,4)=18$, \texttt{ramsey\_four\_four}]
$\arrows{18}{4}{4}$ and $\neg\,\arrows{17}{4}{4}$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper: by color symmetry $\R(4,3)=\R(3,4)=9$, and the Erd\H{o}s--Szekeres step gives $\R(4,4)\le 9+9=18$. Lower: the Paley graph on $\mathbb{Z}/17$, with $a\sim b$ iff $a-b$ is a quadratic residue ($Q=\{1,2,4,8,9,13,15,16\}$), has no red $K_4$ and, being self-complementary, no blue $K_4$.
\end{proof}

\section{The exponential diagonal bound}

\begin{lemma}[Central binomial estimate, \texttt{central\_choose\_le\_four\_pow}]
$\binom{2k}{k}\le 4^k$.
\end{lemma}
\begin{proof}
$\binom{2k}{k}$ is a single term of $\sum_{i=0}^{2k}\binom{2k}{i}=2^{2k}=4^k$.
\end{proof}

\begin{theorem}[Diagonal ceiling, \texttt{arrows\_diagonal\_pow}]
$\arrows{4^k}{k+1}{k+1}$, i.e.\ $\R(k+1,k+1)\le 4^k$.
\end{theorem}
\begin{proof}
$\binom{2k}{k}\to(k+1,k+1)$ by the binomial bound; the estimate above and vertex monotonicity raise the threshold to $4^k$.
\end{proof}

\section{The probabilistic lower bound (exact finite count)}

We realize the Erd\H{o}s first-moment argument as an exact count over colorings of $\mathrm{Fin}\,n$. A coloring is a subset $R$ of the $\binom{n}{2}$ edges; there are $2^{\binom{n}{2}}$ of them. For $T\subseteq V$, $\mathrm{edgesOn}(T)$ is the set of $\binom{|T|}{2}$ internal edges; for $S\subseteq Gr$ the number of subsets of $Gr$ containing $S$ (resp.\ disjoint from $S$) is $2^{|Gr|-|S|}$.

\begin{lemma}[Good coloring exists, \texttt{exists\_good\_coloring}]
If $k\le n$ and $2\binom{n}{k}<2^{\binom{k}{2}}$, there is a coloring with no all-red and no all-blue $k$-set.
\end{lemma}
\begin{proof}[Proof sketch]
Each $k$-set is all-red in $2^{\binom{n}{2}-\binom{k}{2}}$ colorings and all-blue in the same number. Summing over the $\binom{n}{k}$ sets, the bad colorings number at most $2\binom{n}{k}2^{\binom{n}{2}-\binom{k}{2}} < 2^{\binom{n}{2}}$, so a good coloring remains.
\end{proof}

\begin{theorem}[Probabilistic lower bound, \texttt{not\_arrows\_of\_counting}]
If $k\le n$ and $2\binom{n}{k}<2^{\binom{k}{2}}$, then $\neg\,\arrows{n}{k}{k}$, i.e.\ $\R(k,k)>n$.
\end{theorem}

\begin{corollary}[\texttt{not\_arrows\_of\_pow}, \texttt{ramsey\_ten\_lower}]
Using $\binom{n}{k}\le n^k$: if $2n^k<2^{\binom{k}{2}}$ then $\R(k,k)>n$. In particular $\R(10,10)>16$, since $2\cdot 16^{10}=2^{41}<2^{45}=2^{\binom{10}{2}}$.
\end{corollary}

\section{The exponential sandwich for the diagonal}

Instantiate $k=2m$, $n=2^{m-1}$.

\begin{lemma}[Side conditions, \texttt{two\_mul\_le\_two\_pow}, \texttt{prob\_exponent\_lt}]
For $m\ge 4$, $2m\le 2^{m-1}$; for $m\ge 2$, $2(2^{m-1})^{2m}<2^{\binom{2m}{2}}$.
\end{lemma}

\begin{theorem}[Sandwich, \texttt{ramsey\_lower\_even}, \texttt{arrows\_upper\_even}, \texttt{ramsey\_even\_sandwich}]
For all $m\ge 4$,
\[ 2^{\,m-1} \;<\; \R(2m,\,2m) \;\le\; 4^{\,2m-1}. \]
\end{theorem}
\begin{proof}[Proof sketch]
Lower: the exponential corollary with $n=2^{m-1}$, $k=2m$. Upper: the color-diagonal of the diagonal ceiling at $k:=2m-1$.
\end{proof}

Writing $k=2m$, the bounds are $2^{k/2-1}$ and $2^{2(k-1)}$; the exponents differ by about a factor $4$, the still-open constant in $\lim_k \R(k,k)^{1/k}\in[\sqrt 2,4]$. The slack lies entirely in $\binom{n}{k}\le n^k$, not in the method. At $m=3$ the side condition $2m\le 2^{m-1}$ fails, so $m\ge 4$ is the precise boundary.

\section{The arithmetic shadow: van der Waerden and Hales--Jewett}

\begin{theorem}[van der Waerden, AP form]
For every finite color set $\kappa$, every $C:\mathbb{N}\to\kappa$, and every $k$, there exist $a>0$, $b$, and a color $c$ with $C(b+ai)=c$ for all $i<k$; the $k$ terms are distinct.
\end{theorem}
\begin{proof}[Proof sketch]
The canonical corollary of the Hales--Jewett theorem via a monochromatic homothetic copy of $\{0,\dots,k-1\}$ in $\mathbb{N}$: the homothety $s\mapsto a\cdot s+b$ becomes the progression $b+ai$, with returned scalar $a>0$ the common difference; distinctness follows from injectivity of $i\mapsto b+ai$.
\end{proof}

The Hales--Jewett theorem is the structural heart: a high-dimensional combinatorial cube under any finite coloring contains a monochromatic combinatorial line, whose coordinate-sum image is a van der Waerden progression.

\section{Applications, discussion, and future work}

The probabilistic method founded here is the default tool for existence proofs of good codes, expanders, and hard instances; van der Waerden's theorem leads to Szemer\'edi's and Green--Tao theorems. Three directions extend the scaffolding:
\begin{enumerate}
\item \textbf{Deletion method:} allow a few monochromatic cliques and delete a vertex from each, improving the lower bound to $\R(k,k)\gtrsim \tfrac{k}{e}\sqrt2\cdot 2^{k/2}$.
\item \textbf{Off-diagonal counting:} a biased count $\binom{n}{3}p^3+\binom{n}{t}(1-p)^{\binom{t}{2}}$ with $p\asymp t^{-1/2}$ yields $\R(3,t)\gtrsim t^{3/2}$.
\item \textbf{Finite van der Waerden numbers:} derive uniform $W(r,k)$ from Hales--Jewett by compactness.
\end{enumerate}

\section{Conclusion}
On a single arrow-relation framework we have formally established $\R(3,3)=6$, $\R(3,4)=9$, $\R(4,4)=18$ with explicit extremal constructions, the Erd\H{o}s--Szekeres binomial bound, the diagonal ceiling $\R(k+1,k+1)\le 4^k$, the probabilistic lower bound as an exact finite count, and the sandwich $2^{m-1}<\R(2m,2m)\le 4^{2m-1}$, together with the arithmetic shadow van der Waerden / Hales--Jewett.

\end{document}

