from itertools import combinations
from typing import Callable

def is_clique_free(n: int, red: Callable[[int, int], bool], s: int, t: int) -> bool:
    def mono(size: int, want_red: bool) -> bool:
        return any(all(red(a, b) == want_red for a, b in combinations(v, 2))
                   for v in combinations(range(n), size))
    return not mono(s, True) and not mono(t, False)

def pentagon_red(a: int, b: int) -> bool:
    return (a - b) % 5 in (1, 4)

def circulant8_red(a: int, b: int) -> bool:
    return (a - b) % 8 in (1, 4, 7)

def paley17_red(a: int, b: int) -> bool:
    qr = {(x * x) % 17 for x in range(1, 17)}
    return (a - b) % 17 in qr

if __name__ == "__main__":
    print("R(3,3) > 5 via pentagon:", is_clique_free(5, pentagon_red, 3, 3))
    print("R(3,4) > 8 via circulant:", is_clique_free(8, circulant8_red, 3, 4))
    print("R(4,4) > 17 via Paley:", is_clique_free(17, paley17_red, 4, 4))

